INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('338e5f8f-e191-4bcc-9914-21fb7b32856d', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "258272b7-d114-40a7-9498-1a2ff91421d1", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "1b697ae6-a8a8-41a3-88c0-aa9812fded5b", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "8c31b184-2d9c-46cd-ad1a-36bc9ac5ba58", "text": "A tető színét", "isCorrect": false}, {"id": "9af1870a-25b2-4a1d-b38a-5effa57e64d2", "text": "Az épület magasságát", "isCorrect": false}, {"id": "81756698-e92e-4190-a7ff-3c8f69bdd4b1", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "ef97774a-2970-4f55-a8f6-ed004dfc8e1f", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "0614552f-ab1e-4e9f-8800-85e34ff81dd0", "text": "Igaz", "isCorrect": true}, {"id": "02ec1826-124c-4b68-bbd5-99bedc929b91", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c58ec90-b2fa-4c17-b577-a49c4c67c9de", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "46eb564a-6d95-424e-8857-c3d2dd748c43", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "042beabc-5ce7-4063-9c94-7a8026a71b58", "text": "Igaz", "isCorrect": true}, {"id": "e1274c2b-2fdd-4f98-9f3d-94ed504d6fd0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6de48460-cb18-4316-bf1a-ce70ba7a7864", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5e090ec5-c5b6-4644-a81c-363a08c5cf53", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "3bbdf2d6-92dc-4b08-a865-b4418b9bb508", "text": "Igaz", "isCorrect": true}, {"id": "537e44fb-b433-430b-85c8-b0e13f2c8114", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5f7f495-5f2c-48dd-89b5-916ec7d482ca", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec402a75-745f-45fb-a8ea-a18fbb3cbb22', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "87888a74-d21c-45b2-bfe4-dd331d841c55", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "79b2e119-5c79-4d38-abfd-76beee8329c1", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "55450782-0110-4736-b109-61a0a2de146c", "text": "Igaz", "isCorrect": true}, {"id": "e2363457-dc42-4ce5-8fa1-5e40cd880c7b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "173f7741-7776-46db-9bdf-99f60ef5d548", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "6f62c584-8322-4783-bba9-98995b3d7152", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "abdcaada-36c7-415f-8b5d-ca036468388b", "text": "Gömbökből", "isCorrect": false}, {"id": "8660d86c-d146-4799-9154-5ee8e6e44b6f", "text": "Kúpokból", "isCorrect": false}, {"id": "8e7a9295-ef4d-46fb-8954-972d7a872801", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "8f1d2484-8578-438f-a135-0a3b398b0a02", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "9af4707c-a099-4478-ad67-4cf85d8b1382", "text": "Igaz", "isCorrect": true}, {"id": "bbb21178-f3ef-49ff-b931-a997b5b27257", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2592b44e-94ee-4f96-86d4-d91dc5d23cef", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "20e8c162-4d09-400c-b2df-5eb3dd14667e", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "f7ef37c5-65a4-483b-a2ae-71acdef55b8c", "text": "Igaz", "isCorrect": true}, {"id": "9e11706a-e731-4c4f-b3b7-f7b03c7c31ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fd3a6b09-ce5d-4ce8-9d2c-85bd41eb1436", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7be15f9b-314c-496a-8dbc-862e1be03b61', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e4fe0224-03d2-4592-b27f-dca20bd0c06e", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "bff4a175-2cee-4fac-b335-a2dd808453bc", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "2f4682c3-1091-4e33-9048-16b8993573b6", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "562789a0-aae7-4889-b028-4b68e4c7be02", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "fe89af82-bd87-497f-9543-73067a6b9dff", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "f8d34956-dab6-47c5-8b67-abfbe5ac6761", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "89a94fe9-0923-41cb-9e4f-326cc889cc5c", "text": "Igaz", "isCorrect": true}, {"id": "f02cfb99-4ec5-439a-a742-4478c12e92d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b05b2f2-fdee-4bbc-b3e3-efb31d46f263", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "e13228ca-0537-439e-9e3b-3eb2b0f4d57d", "text": "Igaz", "isCorrect": true}, {"id": "cb48a1b9-79d8-42d1-b151-e15f0e584164", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "23405df7-63b5-4bf5-8655-e16593bd17fb", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "02cbb48e-f1b8-489e-b1bf-21d7b5727d99", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "3501e489-a071-4317-b2ce-be678273384d", "text": "Igaz", "isCorrect": true}, {"id": "2fbfdab2-a818-4c5b-ba2a-f4ec5160b2aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "29f305ae-9768-4ede-b277-b2fad03a8a64", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "962245a0-e71a-45d8-973f-81261d3829f7", "text": "Igaz", "isCorrect": true}, {"id": "2bcba48b-c7b8-41f8-9463-c2873bdbaad3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3d528da7-2d86-4f1a-9b29-f2148f507f05", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5d367d29-30e9-4b24-804c-574c356cda50', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e3bd418c-efa9-46b1-a7fb-570a822c7a6b", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "710f163a-3f8e-43ab-9173-6fde307786c3", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "4c7680eb-9dd1-4473-8806-4bf0dc39230d", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "60b5d8ae-adf0-42da-902a-b823fabbe5a4", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "3380809e-ffdf-4d5d-b2dd-b5962916c00b", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "90dfb4fd-853b-47f3-89f0-bb1361dfc80a", "text": "Igaz", "isCorrect": true}, {"id": "7c79aec0-c3c8-4452-83bd-b99c23f88903", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ccea47ad-ffe4-4e52-b8f2-03b633d1b164", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "a8df326a-0da1-4659-af3b-22769a8fac1f", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "093d0f2a-c9c9-411e-9700-f6ffb759055c", "text": "Igaz", "isCorrect": true}, {"id": "87ce7d9f-5a18-48e7-964a-1bf7bb4852cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24b5a110-0dbb-40de-b169-9ae40f6c85bb', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "36b405f3-b089-4b40-bacd-b6afc1318d7f", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "49473783-fa85-4128-a655-c19cc5b68179", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "bc3037c5-46fa-4b42-a202-ca3a93308f95", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "35ed9894-c45a-4cbe-85ad-c8b07539460d", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "054a0c0d-817d-41bf-a1b1-3f7441f863ae", "text": "Igaz", "isCorrect": true}, {"id": "fcc916ba-2078-4c31-94e9-eed323fb2f8a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c0074928-ab77-4ead-853e-92fb6168bfe1", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "d6c0ce61-4b2b-4efe-9666-ffab819eb6ff", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "9a84ffe2-1a5f-41e0-b39f-305722ed2dab", "text": "Igaz", "isCorrect": true}, {"id": "9b068644-5900-4cf2-8b49-be96599390dc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b386671-46df-4637-959c-81b18a5e98e0", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7d131c5c-b995-4c61-80f5-6ba0d5922184', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c08d452c-b598-4f9c-b134-806aeac3143a", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "db604d80-031e-43e6-b2af-f3bc29aaa1fc", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "fc0f75af-6de2-4fbf-9ade-e0bb5f546134", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "c58bdaf5-05d6-40c1-b59a-be29822b3123", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "827880b0-f51a-4d70-91f2-5b9066461d76", "text": "Igaz", "isCorrect": true}, {"id": "d4b17efc-3908-4fe2-afc2-ecc9801b23c4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a9dff45-fc89-420c-aed6-5bf9f2ece06d", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "67ee9ec0-7c89-4c3c-859b-52fefdf36864", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "cc42892c-1ce2-42e9-9532-1c2e8825ca7e", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "f865cbdf-abb4-4a9d-8cda-6890657b2897", "text": "Igaz", "isCorrect": true}, {"id": "4dc4c