INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e090dfb6-87a3-4c7e-b9bd-5700637bd6be', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "23f91b89-3520-4f55-88a9-2bab002bd694", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "e2dbf332-f614-4e86-849c-08995a32fb55", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "14ee1610-aa14-495a-9ce4-c48fe116986e", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "943d96fd-25c3-4a5f-90a8-34920a83399b", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "305643f7-9f47-44bb-a021-b87004bd3d15", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "9717a6c0-934c-4624-8501-d6e28d6142a9", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "ea556790-99f3-4b8d-b00d-07c73012d34a", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "183e6064-2639-496f-9e47-973be8061adb", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "dc4ed6e7-3436-4fc1-a109-5497a0d15350", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "5edf8ee7-fce6-443c-bca8-8c86613a643f", "text": "Igaz", "isCorrect": true}, {"id": "00472bd9-47c9-413d-9cf0-55ef644fb666", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "425a030a-cbb9-4324-8d3a-67138da0367a", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('02f561ef-778d-401a-80cd-5d3812c7f4ef', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "46209fce-2460-4966-b097-17644455ec76", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "316f5aeb-3fd7-430c-9355-5537c2f452e9", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "ff81b201-2f74-461b-85ee-4ba266711496", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "9c6d8840-b787-4b2e-91ef-c76ae1440e3d", "text": "A számláló írása", "isCorrect": false}, {"id": "8f5f3d01-4b09-45cf-9802-c93683e74460", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "912b554c-9ab4-4e16-bb1c-8271b6a76d0b", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "aed457f5-ef48-4d72-a72f-3e928b46f139", "text": "Igaz", "isCorrect": true}, {"id": "bdc3b57b-21aa-4ec9-9172-ec3132f0b58a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a7a181d-4fc6-487e-bde3-6b255ca4ce75", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "e89bd962-67bd-4c59-a659-e7ce2db5d131", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "4654da16-02c9-4558-b263-4e0e8a6370d0", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "05aeed2e-4c1c-4b56-a64a-837f2a115c14", "text": "Igaz", "isCorrect": true}, {"id": "7223e47a-9eea-47ae-b9a9-c39c6ee33404", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2f8887f-27fb-4a6f-90e2-75095c42e505", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bbf94719-82c6-4ff8-a90b-2c9e138b1a22", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "f267e9d8-5912-48c0-9e2d-fd847ecd3d97", "text": "Igaz", "isCorrect": true}, {"id": "f3b71ba1-ca09-490e-8ec1-b9fa989ff8d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('aca42a52-b0ba-4904-b7c0-39b981ca35cd', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "c8838a54-3434-432a-924b-4a0b17ea01c8", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "b7925029-4d4a-4513-8e18-286d027127b4", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "8ca10c94-cf57-491a-a06f-af7ac9cfdf6d", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "60c7228e-1bd3-49c9-8f36-5ff75d563534", "text": "Számok törlése", "isCorrect": false}, {"id": "f58de0e5-0c91-44f7-9e29-f183ad2365f2", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "bc4f7796-daeb-4a0e-aca1-732eb3356459", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "7107c98b-a595-4033-a8d2-cc23ff908da7", "text": "Igaz", "isCorrect": true}, {"id": "78f0f894-63e6-4e74-819a-d9c58d5f8db1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "881ce950-458e-4a79-8eb7-55303a3fe630", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "0336da80-3aab-4cce-a447-716ec6efea67", "text": "Alvás", "isCorrect": true}, {"id": "cf006330-3306-430b-93f9-5f48e2519fcd", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "3d8dd1c3-db82-4f4b-80d0-0433e981214b", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "4b48789b-1142-4d2d-9627-b7a2d1e91ece", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "c80b11be-89d1-4625-a84b-1fa1bdbf1ff1", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "6c6d14ec-763f-4960-80aa-a725877ab0e2", "text": "Igaz", "isCorrect": true}, {"id": "83f3bfbd-afab-48dc-9b51-e54ca1bc7f8d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0a6e91b0-e62c-4092-ae91-4344e5789152", "text": "Hány válaszlehetőség van egy ''igen/nem'' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ef47c879-dbf0-4419-8db5-8843d6a1f30c", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "88f45b66-d15f-47a6-ad86-1df9dec0fa77", "text": "Igaz", "isCorrect": true}, {"id": "2de717f4-c51d-4474-a590-cf68b6608e96", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e1ddebc-a986-4f81-bc56-3171771049c7", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "4ba69f9a-dd4e-45b8-a47c-f5fe778e534f", "text": "Igaz", "isCorrect": true}, {"id": "7f158418-7cf8-4c83-b6d1-1e75be7794fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7de42872-d62c-4f0e-8ec0-74ccb048f662', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "10ee6711-8a4a-4597-98b6-71251b170a67", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "ebdac420-0cec-4aa5-ac0a-e55ef0e6f743", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "654d8728-eedf-42a5-8222-80131130f9ff", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "8bc09db5-a6a1-4296-ab5a-2294b81f3c7f", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "850393fb-4418-49cc-817e-d60a2ba25339", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "2fe0c7dc-8156-418d-9b74-fd67467c239d", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "29461e02-0f12-4ae1-8c5e-5d4029450bb0", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "24ee71ac-282f-474b-aba8-f19717802c2d", "text": "Számok összeadására", "isCorrect": false}, {"id": "10f2eece-08f6-4818-8737-b08abf9f2335", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "d810cae8-cedd-4491-8cc8-e8e9021ea7ca", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "cc003814-5b06-4a12-92dc-fedcd236be73", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "9d5dfb63-7d12-4811-9cf7-93a2b8b1b80c", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "bb33b466-61c3-4724-8948-75249d6b7e9d", "text": "Igaz", "isCorrect": true}, {"id": "1b5afd3d-c34f-45d0-b098-4bdd4ab779e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ec97993-a2c5-4914-b05b-ebf86bcad69c", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "89f5866a-6be9-4fe8-b903-059a246fbf3e", "text": "Igaz", "isCorrect": true}, {"id": "e5c94ac5-2e53-4b37-9a41-7fdd9276b1c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b17329e-9a55-461a-a417-71472638b557", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "4e257df8-c42f-48dd-82e4-946d9d8445e0", "text": "Igaz", "isCorrect": true}, {"id": "d95043ea-5b69-458d-9b6b-32fa848eb4cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9475be1e-e2be-4326-9886-696a8d4b3863", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;